/*
 * Embedded kernel symbol table. The tables live in the .ksyms section,
 * generated by tools/gen_ksyms.py from `nm -n` of a first-pass link. .ksyms is
 * placed after .bss so its size never shifts any other kernel address.
 */
#include <debug.h>
#include <fmt.h>
#include <kstring.h>
#include <platform.h>

extern const u64 ksyms_num;
extern const u64 ksyms_addrs[];
extern const u32 ksyms_offs[];
extern const char ksyms_names[];

u64 ksym_count(void)
{
    return ksyms_num;
}

const char *ksym_lookup(uintptr_t addr, uintptr_t *offset)
{
    if (!ksyms_num || addr < ksyms_addrs[0] || addr >= (uintptr_t)__text_end)
        return NULL;

    /* Largest i with addrs[i] <= addr. */
    u64 lo = 0, hi = ksyms_num;
    while (hi - lo > 1) {
        u64 mid = (lo + hi) / 2;
        if (ksyms_addrs[mid] <= addr)
            lo = mid;
        else
            hi = mid;
    }
    if (offset)
        *offset = addr - ksyms_addrs[lo];
    return ksyms_names + ksyms_offs[lo];
}

uintptr_t ksym_find(const char *name)
{
    for (u64 i = 0; i < ksyms_num; i++)
        if (!strcmp(ksyms_names + ksyms_offs[i], name))
            return ksyms_addrs[i];
    return 0;
}

int ksym_format(char *buf, size_t size, uintptr_t addr)
{
    uintptr_t off;
    const char *name = ksym_lookup(addr, &off);
    if (!name)
        return ksnprintf(buf, size, "%#lx", (unsigned long)addr);
    if (!off)
        return ksnprintf(buf, size, "%s", name);
    return ksnprintf(buf, size, "%s+%#lx", name, (unsigned long)off);
}
